INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26501, 'Acts 20:6', 'Acts', 20, 6, '&nbsp;خو د پتيرې روټۍ د اختر نه وروستو مونږ د فيليپى نه په سمندرى جهاز کښې روان شُو او په پينځو ورځو کښې مونږ د هغوئ سره په ترواس کښې يو ځائ شُو او هلته مونږ يوه هفته تيره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26502, 'Acts 20:7', 'Acts', 20, 7, '&nbsp;د هفتې په اوله ورځ مونږ د روټۍ دپاره راغونډ شوى وُو. پولوس خلقو ته بيان شروع کړو ځکه چې بله ورځ هغۀ غوښتل چې لاړ شى، نو تر نيمې شپې پورې يې خبرې وکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26503, 'Acts 20:8', 'Acts', 20, 8, '&nbsp;هلته پاس په بالاخانه کښې چرته چې مونږ راجمع وُو ډيرې ډيوې بلې شوې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26504, 'Acts 20:9', 'Acts', 20, 9, '&nbsp;يو زلمے چې يوتخوس نوم يې وو، په کړکۍ کښې ناست وو. د پولوس د خبرو په اوږدېدو سره خوب ورله جوټه ورکړه، او چې خوب يوړو نو د درېم چت نه ښکته زمکې ته پرېوتو. چې راوچت يې کړو نو هغه بيا مړ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26505, 'Acts 20:10', 'Acts', 20, 10, '&nbsp;خو پولوس ښکته ورکوز شو او هغه يې په غېږ کښې راوچت کړو او وې وئيل، ”مۀ يرېږئ، تر اوسه پورې ژوندے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26506, 'Acts 20:11', 'Acts', 20, 11, '&nbsp;بيا پولوس بالاخانې ته وختلو، او د عشاء ربانى د روټۍ ماتولو نه وروستو يې د هغوئ سره تر سحره پورې خبرې وکړې او بيا هغه رُخصت شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26507, 'Acts 20:12', 'Acts', 20, 12, '&nbsp;بيا هغوئ هغه زلمے خپل کور ته ژوندے بوتلو او هغوئ ټول بيا ښۀ مطمئن وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26508, 'Acts 20:13', 'Acts', 20, 13, '&nbsp;نو مونږ مخکښې لاړو او په سمندرى جهاز کښې سوارۀ شُو او اَسوس ته روان شُو، هلته نه پولوس هم جهاز ته راختونکے وو. ځکه چې هغۀ دا بندوبست او نيت کړے وو چې د وچې د لارې نه به لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26509, 'Acts 20:14', 'Acts', 20, 14, '&nbsp;کله چې هغه مونږ سره په اَسوس کښې يو ځائ شُو نو مونږ هغه په جهاز کښې سور کړو او ميتيلينے ته يو ځائ لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26510, 'Acts 20:15', 'Acts', 20, 15, '&nbsp;په هغه ورځ مونږ د هغه ځايه روان شُو او د خيوس جزيرې نه تير شُو. او په بله ورځ مونږ ساموس ته ورسېدو او په بل سبا مونږ ميليتوس ته ورسېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26511, 'Acts 20:16', 'Acts', 20, 16, '&nbsp;ځکه چې پولوس دا فېصله کړې وه چې د اِفِسوس نه واوړى نو هغه به د آسيه په علاقه کښې د وخت تېرولو نه بچ شى، هغۀ غوښتل چې څنګه هم کېدے شى چې د پنځوسمې اختر په يروشلم کښې تير کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26512, 'Acts 20:17', 'Acts', 20, 17, '&nbsp;نو پولوس د ميليتوس نه اِفِسوس ته خبر ولېږلو او د جماعت مشران يې راوبلل چې هغۀ سره مِلاو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26513, 'Acts 20:18', 'Acts', 20, 18, '&nbsp;کله چې هغوئ ورله راغلل هغۀ هغوئ ته ووئيل، ”تاسو ته ښۀ پته ده چې د کومې ورځې نه چې ما د آسيه په زمکه اول قدم کېښودو نو ما تاسو سره څنګه وخت تير کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26514, 'Acts 20:19', 'Acts', 20, 19, '&nbsp;ما پوره په عاجزۍ او ژړا سره د مالِک خِدمت وکړو او د يهوديانو سازشونه او آزمېښتونه چې په ما راغلل هغه مې وزغمل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26515, 'Acts 20:20', 'Acts', 20, 20, '&nbsp;تاسو ته پته ده چې ما هيڅ څيز هم چې ستاسو د ښېګړې دپاره وو، پټ ونۀ ساتلو، بلکې ما تاسو ته د خلقو په وړاندې او کور په کور تعليم درکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26516, 'Acts 20:21', 'Acts', 20, 21, '&nbsp;ما يهوديانو او يونانيانو دواړو ته ګواهى ورکړه چې د خُدائ پاک په وړاندې توبه وباسئ او په مالِک عيسىٰ مسيح ايمان راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26517, 'Acts 20:22', 'Acts', 20, 22, '&nbsp;او اوس د روحُ القُدس د غلام په توګه زۀ يروشلم ته روان يم، او هلته چې څۀ ما ته پېښيږى د هغې نه هيڅ خبر نۀ يم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26518, 'Acts 20:23', 'Acts', 20, 23, '&nbsp;خو ما ته روحُ القُدس صرف دا يو خبردارے راکوى چې په هر ښار کښې قېد او تکليفونه ستا انتظار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26519, 'Acts 20:24', 'Acts', 20, 24, '&nbsp;خو زۀ د خپل ژوند هيڅ پرواه نۀ ساتم، او زما خواهش صرف دا دے چې خپله منډه سر ته ورسوم او هغه خِدمت پوره کړم چې مالِک عيسىٰ ما ته سپارلے دے، يعنې چې د خُدائ پاک د فضل د زيرى په حقله خلقو ته ګواهى ورکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26520, 'Acts 20:25', 'Acts', 20, 25, '&nbsp;تاسو ټولو او هغه چا ته چې ما د خُدائ پاک د بادشاهۍ بيان کړے دے اوس زۀ په دې پوهېږم چې تاسو به کله هم زما مخ بيا ونۀ وينئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26521, 'Acts 20:26', 'Acts', 20, 26, '&nbsp;نو ځکه زۀ نن دا اِعلان کوم چې زما په غاړه د چا د خُون ذمه وارى هم نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26522, 'Acts 20:27', 'Acts', 20, 27, '&nbsp;ځکه چې ما تاسو ټولو نه د خُدائ پاک مقصد او يوه خبره هم د بيانولو نه، نۀ ده پټه کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26523, 'Acts 20:28', 'Acts', 20, 28, '&nbsp;د خپل ځان او د هغه ټولې رمې خيال ساتئ کومه چې روحُ القُدس ستاسو په حواله کړې ده او د خُدائ پاک د هغه جماعت شپونتوب وکړئ کوم چې هغۀ د خپل زوئ د وينې په قيمت په بيعه اخستے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26524, 'Acts 20:29', 'Acts', 20, 29, '&nbsp;ما ته پته ده چې زما د تلو نه پس به په تاسو کښې داړونکى ليوان راشى او رمه به په امان پرې نۀ ږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26525, 'Acts 20:30', 'Acts', 20, 30, '&nbsp;ستاسو په ډله کښې به هم څۀ خلق داسې راپاڅى چې رښتيا به په دروغو بدل کړى او په دې به مريدان خپل ځان ته راواړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26526, 'Acts 20:31', 'Acts', 20, 31, '&nbsp;نو په دې وجه خبردار اوسئ، او دا خبره ياد ساتئ چې ما تر درېو کالو پورې شپه او ورځ په تاسو کښې هر يو ته په ژړا انګولا سره تعليم درکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26527, 'Acts 20:32', 'Acts', 20, 32, '&nbsp;او اوس زۀ تاسو خُدائ پاک او د هغۀ د فضل کلام ته حواله کوم، هغه کلام ته چې تاسو آبادوى او تاسو ته په هغوئ ټولو کښې ميراث درکوى څوک چې پاک دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26528, 'Acts 20:33', 'Acts', 20, 33, '&nbsp;ما د چا نه هم د سپينو زرو او يا د سرو زرو يا د جامو خواهش نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26529, 'Acts 20:34', 'Acts', 20, 34, '&nbsp;تاسو ټول په خپله ښۀ خبر يئ چې ما په خپلو لاسونو کار کړے دے او د ځان او د خپلو ملګرو حاجتونه مې پوره کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26530, 'Acts 20:35', 'Acts', 20, 35, '&nbsp;په دې هر څۀ کښې ما تاسو ته مثال درکړو چې په دې طريقه مونږ ته په کار دى چې د غريبانانو مدد وکړو او د مالِک عيسىٰ خبرې ياد ساتو چې هغۀ په خپله فرمائيلى دى چې، د اخستو نه په ورکړه کښې برکت ډېر دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26531, 'Acts 20:36', 'Acts', 20, 36, '&nbsp;کله چې هغۀ خبرې ختمې کړې نو پولوس د هغوئ ټولو سره خُدائ پاک ته په سجده شو او دُعا يې وغوښته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26532, 'Acts 20:37', 'Acts', 20, 37, '&nbsp;بيا هغوئ ټولو وژړل او پولوس له يې غاړه ورکړه او ښکل يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26533, 'Acts 20:38', 'Acts', 20, 38, '&nbsp;هغوئ په دې خبره زيات خفه شول چې هغۀ ووئيل چې دوئ به بيا کله هم د هغۀ مخ ونۀ وينى. بيا هغوئ ورسره تر کشتۍ پورې لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26534, 'Acts 21:1', 'Acts', 21, 1, '&nbsp;کله چې مونږ د هغوئ نه رُخصت شُو او جهاز روان شو، نو مونږ نېغ د قوس جزيرې ته راغلو او په بله ورځ رودوس ته او د هغه ځائ نه پاترا ته لاړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26535, 'Acts 21:2', 'Acts', 21, 2, '&nbsp;هلته مونږ يوه کشتۍ ولاړه وليده چې فينيکې ته تياره وه. مونږ وروختلو او په هغې کښې مو سفر وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26536, 'Acts 21:3', 'Acts', 21, 3, '&nbsp;مونږ په لاره کښې د قبرص جزيره وليده او ترې نه په ګس لاس تير شُو. مونږ شام ته سفر جارى وساتلو او په صور کښې کوز شُو ځکه چې هلته يې د کشتۍ نه سامان کوزولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26537, 'Acts 21:4', 'Acts', 21, 4, '&nbsp;مونږ مريدان وموندل او هلته يوه هفته ورسره ايسار شُو. هغوئ د روحُ القُدس په هدايت پولوس ته ووئيل چې، ”يروشلم ته مۀ ځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26538, 'Acts 21:5', 'Acts', 21, 5, '&nbsp;نو کله چې زمونږ ورځې پوره شوې نو مونږ له هغه ځائ نه په خپل سفر روان شُو. او هغوئ ټول سره د ښځو او بچو، مونږ سره د ښار نه بهر راووتل او هلته مونږ د سمندر په غاړه په سجده شُو او د خُدائ پاک نه مو دُعا وغوښتله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26539, 'Acts 21:6', 'Acts', 21, 6, '&nbsp;بيا مونږ يو بل سره خُدائ په امانى وکړه او مونږ کشتۍ ته وختلو او هغوئ خپل کور ته واپس لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26540, 'Acts 21:7', 'Acts', 21, 7, '&nbsp;د صور نه زمونږ سفر جارى وو او بيا مونږ پتوليمَس ته راغلو، او مونږ د ايماندارانو سره مِلاو شُو او د هغوئ سره د يوې ورځې دپاره پاتې شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26541, 'Acts 21:8', 'Acts', 21, 8, '&nbsp;په بله ورځ مونږ روان شُو او قيصريه ته راغلو، او مونږ د فيليپوس مېلمانۀ شُو چې د زيرى دعوت ورکوونکے وو. او هغه د هغه اوو کسانو نه يو وو څوک چې د خوراک تقسيمولو دپاره غوره کړے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26542, 'Acts 21:9', 'Acts', 21, 9, '&nbsp;د هغۀ څلور پېغلې لوڼه وې چې نبوت به يې کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26543, 'Acts 21:10', 'Acts', 21, 10, '&nbsp;مونږ چې هلته يو څو ورځو دپاره ايسار وُو نو د يهوديه نه اګابوس نومې يو نبى راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26544, 'Acts 21:11', 'Acts', 21, 11, '&nbsp;هغه مونږ له راغلو، او د پولوس ملابند يې واخستو او په دې يې خپل لاس او پښې وتړل او وې وئيل چې، ”روحُ القُدس دا وائى چې په يروشلم کښې به يهوديان په دې طريقه د دې ملابند مالِک وتړى او هغه به غېر‌يهوديانو ته په حواله کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26545, 'Acts 21:12', 'Acts', 21, 12, '&nbsp;مونږ چې دا خبرې واورېدلې نو مونږ او نورو مقامى ايماندارانو پولوس ته منت وکړو چې يروشلم ته لاړ نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26546, 'Acts 21:13', 'Acts', 21, 13, '&nbsp;خو پولوس جواب ورکړو، ”تاسو ولې ژاړئ او زما زړۀ ماتوئ؟ ځکه چې زۀ نۀ يواځې تړلو ته، بلکې دې ته هم تيار يم چې د مالِک عيسىٰ دپاره په يروشلم کښې شهيد شم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26547, 'Acts 21:14', 'Acts', 21, 14, '&nbsp;بيا چې هغۀ ونۀ منل نو مونږ چُپ پاتې شُو او ومو وئيل چې، ”د مالِک مرضى دې پوره شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
