(26590, 'Acts 22:17', 'Acts', 22, 17, '&nbsp;کله چې زۀ يروشلم ته واپس راغلم او ما د خُدائ په کور کښې دُعا کوله نو زۀ بې‌خوده شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26591, 'Acts 22:18', 'Acts', 22, 18, '&nbsp;او عيسىٰ مې وليدو چې ما ته فرمائى چې زر کوه او سمدستى د يروشلم نه اوځه، ځکه چې دوئ به زما په حقله ستا ګواهى قبوله نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26592, 'Acts 22:19', 'Acts', 22, 19, '&nbsp;ما ورته ووئيل چې مالِکه هغوئ ته دا معلومه ده چې په هره عبادتخانه کښې به ما هغوئ نيول او په کوړو به مې وهل د چا به چې په تا ايمان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26593, 'Acts 22:20', 'Acts', 22, 20, '&nbsp;او کله چې ستا د ګواه ستِفانوس وينه توئ شوله نو زۀ په خپله هلته موجود وم او پرې راضى وم او د هغوئ د جامو څوکۍ مې کوله چا چې هغه مړ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26594, 'Acts 22:21', 'Acts', 22, 21, '&nbsp;بيا هغۀ ما ته ووئيل، لاړ شه، ځکه چې زۀ تا لرې لرې غېر يهودى قومونو ته لېږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26595, 'Acts 22:22', 'Acts', 22, 22, '&nbsp;تر دې خبرو پورې هغوئ هغۀ ته غوږ نيولے وو، خو بيا هغوئ چغې کړې، ”د داسې سړى مخ دې ورک شى، دا د پرېښودو قابل نۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26596, 'Acts 22:23', 'Acts', 22, 23, '&nbsp;او هغوئ لا نورې چغې کړې، خپلې جامې يې وشلولې او خاورې يې بره نوستلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26597, 'Acts 22:24', 'Acts', 22, 24, '&nbsp;نو کمان آفسر حُکم وکړو چې، ”پولوس قلعې ته واپس بوځئ،“ او هدايت يې ورکړو چې، ”په کوړو وهلو ترې بيان واخلئ او دا وجه ترې معلومه کړئ چې د هغۀ خلاف دا هنګامه ولې راپورته شوې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26598, 'Acts 22:25', 'Acts', 22, 25, '&nbsp;خو کله چې هغوئ هغه د وهلو دپاره وتړلو نو پولوس هلته ولاړ صوبه دار ته ووئيل چې، ”ولې دا ستا دپاره جائز دى چې تۀ يو مقامى رومى په کوړو وهې چې جرم پرې ثابت نۀ وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26599, 'Acts 22:26', 'Acts', 22, 26, '&nbsp;کله چې صوبه دار دا واورېدل نو هغه کمان آفسر ته ورغلو او هغۀ ته يې ووئيل چې، ”تۀ څۀ کول غواړې؟ دا سړے خو مقامى رومى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26600, 'Acts 22:27', 'Acts', 22, 27, '&nbsp;کمان آفسر پولوس له راغلو او تپوس يې ترې وکړو، ”ما ته ووايه چې تۀ رښتيا مقامى رومى يې څۀ؟“ او هغۀ ووئيل چې، ”آو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');